package org.apache.commons.lang.time;

import junit.framework.TestCase;
import java.util.Calendar;

public class AgentBRT_Lang_63_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        Calendar start = Calendar.getInstance();
        Calendar end = Calendar.getInstance();

        // Set start to January 31st
        start.set(2023, Calendar.JANUARY, 31);
        // Set end to March 31st
        end.set(2023, Calendar.MARCH, 31);

        // Attempt to reduce by 2 months
        int difference = 2;
        int result = DurationFormatUtils.reduceAndCorrect(start, end, Calendar.MONTH, difference);

        // The expected behavior is that the end date should be corrected to January 31st
        // and the result should be the number of months corrected, which is 2.
        assertEquals("The reduceAndCorrect method did not return the expected correction value.", 2, result);
        assertEquals("The end calendar was not corrected to the expected date.", start.get(Calendar.MONTH), end.get(Calendar.MONTH));
        assertEquals("The end calendar day was not corrected to the expected day.", start.get(Calendar.DAY_OF_MONTH), end.get(Calendar.DAY_OF_MONTH));
    }
}

